/* rustty_config::Config — the config handle built by the config C-ABI. */
typedef struct Config Config;
/* rustty_apprt_api::ClipboardRequest — the boxed clipboard request handle. */
typedef struct ClipboardRequest ClipboardRequest;
/* rustty_input::binding::FlagsC — the `input.Binding.Flags.C` out-param. */
