/* ---- Options (ghostty_runtime_config_s, embedded.Options, #[repr(C)]; size 64) ----
 * The 7 host callbacks (ADV-FIX 7: THIS typedef set + the smoke KAT's typed stubs
 * are the fn-ptr-ABI backstop). `close_surface` is nullable (reference `?*const fn`). */
typedef struct {
    void *userdata;
    bool supports_selection_clipboard;
    void (*wakeup)(void *userdata);
    bool (*action)(App *app, TargetC target, ActionC action);
    ClipboardReadResult (*read_clipboard)(void *userdata,
                                          int req_type,
                                          ClipboardRequest *state,
                                          const char *const *mimes,
                                          uintptr_t mimes_len,
                                          bool list);
    void (*confirm_read_clipboard)(void *userdata,
                                   const ClipboardConfirm *confirm,
                                   ClipboardRequest *state,
                                   ClipboardRequestType req_type);
    void (*write_clipboard)(void *userdata,
                            int req_type,
                            const ClipboardContent *contents,
                            uintptr_t len,
                            bool confirmed);
    void (*close_surface)(void *userdata, bool process_alive);
} Options;

/* ---- SurfaceOptions (ghostty_surface_config_s, embedded.SurfaceOptions, #[repr(C)]; size 88) ---- */
